class Can {
	constructor(x, y, size) {
		this.x = x;
		this.y = y;
		this.a = 0;
		this.av = random(-1, 1);
		if (abs(this.av) < 0.1) this.av = random(0.1, 0.9);
		this.size = size;
	}
	show() {
		push();
		shininess(2);
		translate(this.x, this.y, 0);
		rotateX(this.a);
		rotateY(75 + this.a);
		noStroke();
		texture(img);
		cylinder(1.1 * this.size, 3.2 * this.size, 24, 1, false, false);
		specularMaterial(150);
		cylinder(1.09 * this.size, 3.2 * this.size);
		translate(0, 1.62 * this.size, 0);
		push();
		rotateX(90);
		torus(.9 * this.size, 0.02 * this.size,72,12);
		torus(.7 * this.size, 0.02 * this.size,72,12);
		specularMaterial(180);
		torus(1.08 * this.size, 0.04 * this.size,72,12);
		pop();
		translate(0, -3.24 * this.size, 0);
		push();
		rotateX(90);
		specularMaterial(130);
		torus(.9 * this.size, 0.02 * this.size,72,12);
		torus(.7 * this.size, 0.02 * this.size,72,12);
		specularMaterial(180);
		torus(1.08 * this.size, 0.04 * this.size,72,12);
		pop();
		pop();
	}
	move() {
		this.a += this.av;
	}
	upright() {
		this.a = lerp(this.a, 0, 0.1);
	}
}

