let img;
const masterSize = 40;
let cans = [];
let zoom;
let zvel = 0;
let xpos = 0;
let xvel = 0;
let lpos, mpos;
let paused = false;
let upright = false;

function preload() {
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/souplabel.jpg');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(DEGREES);
	for (let y = -height / 2 + masterSize; y < height / 2; y += (Math.max(0.001, Math.abs(4 * masterSize)) || 1)) {
		for (let x = -width / 2 + 0.75 * masterSize; x < width / 2; x += (Math.max(0.001, Math.abs(3 * masterSize)) || 1)) {
			cans.push(new Can(x, y, masterSize));
		}
	}
	zoom = 1.2 * height;
	lpos = createVector(0, 0);
	mpos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function draw() {
	background(0);
	setLighting();
	zoomCamera();
	for (let c of cans) {
		if (frameCount > 90 && paused == false) {
			c.move();
		} else if (upright) {
			c.upright();
		}
		c.show();
	}
}

function setLighting() {
	ambientLight(195, 155, 155);
	mpos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
	mpos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
	lpos.lerp(mpos, 0.1);
	pointLight(100, 100, 100, lpos.x, lpos.y, 250);
}

function zoomCamera() {
	zoom += zvel;
	zvel *= 0.99;
	xpos += xvel;
	xvel *= 0.99;
	if (zoom < 200) {
		zvel *= -1;
	}
	if (xpos > 1200 || xpos < -1200) {
		xvel *= -1
	};
	if (keyIsDown(UP_ARROW)) {
		zvel -= 0.2;
	}
	if (keyIsDown(DOWN_ARROW)) {
		zvel += 0.2;
	}
	if (keyIsDown(LEFT_ARROW)) {
		xvel -= 0.2;
	}
	if (keyIsDown(RIGHT_ARROW)) {
		xvel += 0.2;
	}
	camera(xpos, 0, zoom, 0, 0, 0, 0, 1, 0);
}

function keyPressed() {
	if (keyCode == 32) {
		paused = !paused;
		upright = false;
	}
	if (keyCode == 82) {
		paused = true;
		upright = true;
	}

}
